<?php
declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('tickets.create');$pdo=db();$user=current_user();$pageTitle='Nuevo ticket de soporte';$errors=[];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$subject=trim((string)($_POST['subject']??''));$message=trim((string)($_POST['message']??''));$category=(string)($_POST['category']??'general');$priority=(string)($_POST['priority']??'normal');$department=trim((string)($_POST['department']??setting('support_default_department','Soporte')));if($subject===''||$message==='')$errors[]='Completa el asunto y la descripción.';if(!in_array($priority,['low','normal','high','urgent'],true))$priority='normal';if(!$errors){$hours=(int)setting('support_sla_'.$priority.'_hours',$priority==='urgent'?'4':($priority==='high'?'8':($priority==='low'?'48':'24')));$sla=date('Y-m-d H:i:s',time()+$hours*3600);$num='TCK-'.date('ymd').'-'.strtoupper(substr(bin2hex(random_bytes(4)),0,6));$pdo->beginTransaction();try{$st=$pdo->prepare("INSERT INTO support_tickets(ticket_number,user_id,subject,category,department,priority,status,stage,sla_due_at,last_reply_by,message) VALUES(?,?,?,?,?,?, 'open','new',?,?,?)");$st->execute([$num,(int)$user['id'],$subject,$category,$department?:'Soporte',$priority,$sla,(int)$user['id'],$message]);$id=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO support_ticket_events(ticket_id,user_id,event_type,title,details) VALUES(?,?,?,?,?)")->execute([$id,(int)$user['id'],'created','Ticket creado','Solicitud recibida en la mesa de soporte']);$pdo->commit();$mail=send_system_email((string)setting('support_email','info@socrates.la'),'Nuevo ticket '.$num,'<h2>'.e($subject).'</h2><p>'.nl2br(e($message)).'</p>');flash($mail['success']?'success':'info',$mail['success']?'Ticket creado y soporte notificado.':'Ticket creado. El email de aviso no pudo enviarse: '.$mail['error']);redirect('support_ticket_view.php?id='.$id);}catch(Throwable$e){$pdo->rollBack();$errors[]=$e->getMessage();}}}require __DIR__.'/includes/header.php';?><?php foreach($errors as$e):?><div class="alert alert-error"><?=e($e)?></div><?php endforeach;?><div class="project-hero compact"><div><span class="eyebrow">NUEVO CASO</span><h2>Solicitar soporte</h2><p>Describe el problema con contexto suficiente. El sistema conservará toda la trazabilidad del caso.</p></div></div><section class="panel"><form method="post" class="panel-body form-grid"><?=csrf_field()?><label class="full">Asunto<input name="subject" required value="<?=e($_POST['subject']??'')?>" placeholder="Ej.: Error al enviar una cotización"></label><label>Categoría<select name="category"><option value="general">General</option><option value="project">Proyecto</option><option value="billing">Facturación</option><option value="email">Email / SMTP</option><option value="integration">Integración</option><option value="security">Seguridad</option></select></label><label>Prioridad<select name="priority"><option value="normal">Normal</option><option value="low">Baja</option><option value="high">Alta</option><option value="urgent">Urgente</option></select></label><label class="full">Descripción<textarea name="message" rows="8" required placeholder="Qué intentabas hacer, qué ocurrió y qué resultado esperabas."><?=e($_POST['message']??'')?></textarea></label><div class="full alert alert-info"><strong>Ruta del ticket:</strong> Recibido → Clasificación → En trabajo → Esperando respuesta (si aplica) → Resuelto → Cerrado.</div><div class="full form-actions"><a class="btn btn-light" href="support.php">Cancelar</a><button class="btn btn-primary">CREAR TICKET</button></div></form></section><?php require __DIR__.'/includes/footer.php';?>
